def beat_seconds(bid, default):
    """The beat's measured narration length (the clock). Falls back when run outside the reel."""
    try:
        for b in json.loads((HERE / "beat_sheet.json").read_text())["beats"]:
            if b["beat_id"] == bid:
                return float(b.get("render_duration_s") or b.get("actual_duration_s") or default)
    except Exception:
        pass
    return default


def T(s, size=30, color=INK, font=SANS, weight="NORMAL", **kw):
    """Text built at 48 pt and scaled (avoids Pango's small-size glyph gaps)."""
    return Text(s, font=font, font_size=48, color=color, weight=weight, **kw).scale(max(size, 26) / 48)


def stack(*lines, size=30, color=INK, font=SANS, weight="NORMAL", buff=0.1, aligned=LEFT):
    return VGroup(*[T(s, size, color, font, weight) for s in lines]).arrange(DOWN, buff=buff, aligned_edge=aligned)


def place(m, x=None, y=None, left=None, top=None, right=None, bottom=None):
    """Position by an edge or the center, in frame units."""
    if left is not None:
        m.shift((left - m.get_left()[0]) * RIGHT)
    if right is not None:
        m.shift((right - m.get_right()[0]) * RIGHT)
    if x is not None:
        m.shift((x - m.get_center()[0]) * RIGHT)
    if top is not None:
        m.shift((top - m.get_top()[1]) * UP)
    if bottom is not None:
        m.shift((bottom - m.get_bottom()[1]) * UP)
    if y is not None:
        m.shift((y - m.get_center()[1]) * UP)
    return m


def clamp(m):
    """Keep a mobject inside the title-safe width."""
    if m.get_left()[0] < -SX:
        place(m, left=-SX)
    if m.get_right()[0] > SX:
        place(m, right=SX)
    return m


def hai_mark(height, color=INK, opacity=1.0):
    """The Humanitarians AI mark (logos/humanitarians/humanitarians-logo-1.svg), as polygons."""
    polys = [[(0, 0), (74, 0), (74, 148), (178, 148), (206, 218), (74, 218), (74, 368), (0, 368)],
             [(81, 1), (153, 1), (302, 367), (228, 367)],
             [(237, 0), (311, 0), (311, 368), (237, 368)]]
    g = VGroup(*[Polygon(*[np.array([x, -y, 0.0]) for x, y in p], stroke_width=0,
                         fill_color=color, fill_opacity=opacity) for p in polys])
    return g.scale_to_fit_height(height)


def headline(landscape, *portrait):
    """Serif headline, top-left, with a gold highlighter rule beneath."""
    lines = portrait if PORTRAIT else (landscape,)
    h = stack(*lines, size=40 if PORTRAIT else 46, font=SERIF, buff=0.04)
    place(h, left=-SX, top=SY)
    rule = Rectangle(width=h.width, height=0.07, stroke_width=0, fill_color=GOLD, fill_opacity=1)
    place(rule, left=-SX, top=h.get_bottom()[1] - 0.1)
    return VGroup(h, rule)


class Beat:
    """Timing helpers. run.sh only discovers scene classes that subclass Scene directly, so these
    methods are attached to Scene below instead of being inherited from a subclass."""
    BID, DEFAULT = "B00", 10.0

    def begin(self):
        self.camera.background_color = CREAM
        self.D = beat_seconds(self.BID, self.DEFAULT)
        self.el = 0.0
        self.add(place(hai_mark(0.42, INK, 0.3), right=SX, bottom=-SY))

    def P(self, *anims, rt=1.0):
        self.play(*anims, run_time=rt)
        self.el += rt

    def at(self, frac):
        """Hold until this fraction of the narration."""
        t = frac * self.D
        if t - self.el > 0.02:
            self.wait(t - self.el)
            self.el = t

    def end(self):
        self.at(1.0)


for _name in ("begin", "P", "at", "end"):
    setattr(Scene, _name, getattr(Beat, _name))


class Box:
    """Maps data coordinates into a rectangle of the frame."""

    def __init__(self, x0, y0, x1, y1, xr, yr):
        self.x0, self.y0, self.x1, self.y1, self.xr, self.yr = x0, y0, x1, y1, xr, yr

    def p(self, x, y):
        fx = (x - self.xr[0]) / (self.xr[1] - self.xr[0])
        fy = (y - self.yr[0]) / (self.yr[1] - self.yr[0])
        return np.array([self.x0 + fx * (self.x1 - self.x0), self.y0 + fy * (self.y1 - self.y0), 0.0])

    def line(self, xs, ys, color, width=5):
        pts = [self.p(x, min(y, self.yr[1])) for x, y in zip(xs, ys)]   # clipped at the top of the box
        return VMobject(stroke_color=color, stroke_width=width).set_points_as_corners(pts)


def axes(box, yticks, xticks, xlabel=None, size=28):
    """Baseline, y gridlines and tick labels, all kept clear of the plot area."""
    g = VGroup(Line(box.p(box.xr[0], box.yr[0]), box.p(box.xr[1], box.yr[0]), stroke_color=INK, stroke_width=3))
    for v, s in yticks:
        if v != box.yr[0]:
            g.add(DashedLine(box.p(box.xr[0], v), box.p(box.xr[1], v), stroke_color=GREY, stroke_width=1.5,
                             dash_length=0.06))
        g.add(place(T(s, size, SLATE), right=box.x0 - 0.12, y=box.p(box.xr[0], v)[1]))
    for v, s in xticks:
        g.add(place(T(s, size, SLATE), x=box.p(v, 0)[0], top=box.y0 - 0.12))
    if xlabel:
        g.add(clamp(place(T(xlabel, size, SLATE), x=(box.x0 + box.x1) / 2, top=box.y0 - 0.55)))
    return g


def swatch(color, label, kind="solid", size=28, buff=0.16):
    if kind == "line" and not PORTRAIT:
        mark = Line(LEFT * 0.25, RIGHT * 0.25, stroke_color=color, stroke_width=7)
    elif kind == "outline":
        mark = Square(0.28, stroke_color=color, stroke_width=5, fill_opacity=0)
    else:   # a short bar: a thin swatch line reads as a small text run in 9:16
        mark = Rectangle(width=0.34, height=0.24, stroke_width=0, fill_color=color, fill_opacity=1)
    return VGroup(mark, T(label, size)).arrange(RIGHT, buff=buff)


def chip(*lines, color=SLATE, size=30, weight="NORMAL", width=4):
    """Text in a rounded box. Slate outline: an ink outline reads as a text run to GATE T."""
    t = stack(*lines, size=size, weight=weight, buff=0.05, aligned=LEFT)
    return VGroup(SurroundingRectangle(t, buff=0.16, stroke_color=color, stroke_width=width, corner_radius=0.1), t)


def k_label(v):
    return f"{v / 1000:.0f}k"


# --------------------------------------------------------------------------------------------
# Shared: the 360 stress cases as rows of squares, one row per change (evidence stress.<agent>.grid).
# 60 squares per change = 4 test sets x 15 runs, drawn as 2 rows of 30; filled = beats HPA at the same cost.
# --------------------------------------------------------------------------------------------
def case_rows(agent, top):
    g = ST[agent]["grid"]
    if PORTRAIT:
        sq, gap, row_gap, size = 0.105, 0.022, 0.05, 26
    else:
        sq, gap, row_gap, size = 0.21, 0.045, 0.16, 30
    rows, fills, counts, cells_by = VGroup(), VGroup(), VGroup(), {}
    y = top
    for change in E["changes"]:
        bits = g[change]
        label = T(LABELS[change], size)
        count = T(f"{bits.count('1')}/60", size, weight="BOLD")
        cells = VGroup(*[Square(sq, stroke_color=SLATE, stroke_width=2.5, fill_opacity=0) for _ in range(60)])
        cells.arrange_in_grid(rows=2, cols=30, buff=gap)
        if PORTRAIT:   # label and count on one line, the squares under it
            place(label, left=-SX, top=y)
            place(count, right=SX, top=y)
            place(cells, left=-SX, top=label.get_bottom()[1] - 0.03)
            y = cells.get_bottom()[1] - row_gap
        else:          # label | squares | count
            place(cells, left=-SX + 3.35, top=y)
            place(label, left=-SX, y=cells.get_center()[1])
            place(count, left=cells.get_right()[0] + 0.25, y=cells.get_center()[1])
            y = cells.get_bottom()[1] - row_gap
        fill = VGroup(*[Square(sq, stroke_width=0, fill_color=TEAL, fill_opacity=1).move_to(c)
                        for c, b in zip(cells, bits) if b == "1"])
        rows.add(VGroup(label, cells))
        fills.add(fill)
        counts.add(count)
        cells_by[change] = cells
    return rows, fills, counts, cells_by


def worst_mark(cells_by, agent):
    w = ST[agent]["worst_case"]
    return SurroundingRectangle(cells_by[w["change"]][w["index"]], buff=0.03, stroke_color=CRIMSON, stroke_width=6)


# --------------------------------------------------------------------------------------------
# Shared: a log number line for the factor that scales a history day (0.1x to 5x), plus a point for 0.
# --------------------------------------------------------------------------------------------
class FactorLine:
    def __init__(self, y, size):
        self.x0 = -SX + (0.9 if PORTRAIT else 2.2)   # x of factor 0.1
        self.x1 = SX - (0.4 if PORTRAIT else 0.6)    # x of factor 5
        self.z = -SX + (0.25 if PORTRAIT else 0.9)   # x of factor 0
        self.y = y
        self.axis = VGroup(Line([self.x0, y, 0], [self.x1, y, 0], stroke_color=INK, stroke_width=4),
                           Dot([self.z, y, 0], radius=0.05, color=INK))
        self.ticks = VGroup()
        for f, s in ((0.1, "× 0.1"), (1.0, "× 1"), (5.0, "× 5")):
            x = self.x(f)
            self.ticks.add(Line([x, y - 0.08, 0], [x, y + 0.08, 0], stroke_color=INK, stroke_width=4))
            self.ticks.add(place(T(s, size, SLATE), x=x, top=y - 0.24))
        self.ticks.add(place(T("0", size, SLATE), x=self.z, top=y - 0.24))

    def x(self, f):
        if f <= 0:
            return self.z
        return self.x0 + (math.log10(f) + 1) / (math.log10(5) + 1) * (self.x1 - self.x0)


