# B02: HPA's target, set by the agent each minute (train.py Headroom), and the 35 numbers it sees (env.py _obs).
# --------------------------------------------------------------------------------------------
class B02_Setup(Scene):
    BID, DEFAULT = "B02", 15.19

    def construct(self):
        self.begin()
        O, X = E["observation"], E["example"]
        cap = O["capacity_per_server"]
        LOAD = 6000   # illustrative load (requests per minute) for the server row; servers = ceil(load / (600 x target))
        hl = headline("What the agent controls, and sees", "What the agent", "controls, and sees")
        size = 26 if PORTRAIT else 30
        top = hl.get_bottom()[1] - 0.3
        hpa = (stack("HPA: enough servers", "that each runs near", "a target load", size=26, buff=0.05) if PORTRAIT
               else T("HPA: enough servers that each runs near a target load", 32))
        place(hpa, left=-SX, top=top)
        if PORTRAIT:   # no box (the padding would cross the safe edge): a slate rule above the lines
            lines = stack("agent: reinforcement", "learning (RL), with", "Proximal Policy", "Optimization (PPO)",
                          size=26, buff=0.04)
            rule = Rectangle(width=lines.width, height=0.07, stroke_width=0, fill_color=SLATE, fill_opacity=1)
            place(rule, left=-SX, bottom=lines.get_top()[1] + 0.1)
            agent = VGroup(rule, lines)
        else:
            agent = chip("the agent: reinforcement learning (RL),", "trained with Proximal Policy Optimization (PPO),",
                         "sets the target every minute", size=32)
        # the target slider
        tx0, tx1 = -SX + (0.45 if PORTRAIT else 0.5), SX - (0.45 if PORTRAIT else 0.5)
        if PORTRAIT:   # the agent chip replaces the HPA line, so the slider sits under the taller of the two
            ty = top - agent.height - 0.85
        else:
            ty = hpa.get_bottom()[1] - 1.25
        tpos = lambda t: tx0 + (t - 40) / 50 * (tx1 - tx0)
        track = Line([tx0, ty, 0], [tx1, ty, 0], stroke_color=SLATE, stroke_width=6)
        ticks = VGroup(*[Line([tpos(t), ty - 0.1, 0], [tpos(t), ty + 0.1, 0], stroke_color=SLATE, stroke_width=4)
                         for t in O["targets_pct"]])
        ends = VGroup(place(T("40%", size, SLATE), x=tpos(40), top=ty - 0.18),
                      place(T("90%", size, SLATE), x=tpos(90), top=ty - 0.18),
                      place(T("target" if PORTRAIT else "HPA's target, set by the agent each minute",
                              size, SLATE), x=(tx0 + tx1) / 2, top=ty - 0.18))

        def marker(t):
            tri = Triangle(stroke_width=0, fill_color=GOLD, fill_opacity=1).scale(0.14).rotate(PI)
            place(tri, x=tpos(t), bottom=ty + 0.06)
            val = place(T(f"{t}%", size, weight="BOLD"), x=tpos(t), bottom=tri.get_top()[1] + 0.06)
            return VGroup(tri, val)

        stop = ty - (0.75 if PORTRAIT else 0.85)

        def servers(t):
            n = math.ceil(LOAD / (cap * t / 100))
            s = 0.26 if PORTRAIT else 0.38
            g = VGroup(*[Square(s, stroke_width=0, fill_color=SLATE, fill_opacity=1) for _ in range(n)])
            g.arrange_in_grid(cols=10 if PORTRAIT else 25, buff=0.07 if PORTRAIT else 0.1, flow_order="rd")
            return place(g, left=-SX, top=stop)

        srv_cap = T("servers HPA runs" if PORTRAIT else "servers HPA runs for 6,000 requests a minute", size, SLATE)
        place(srv_cap, left=-SX, top=servers(40).get_bottom()[1] - 0.2)
        if PORTRAIT:
            place(agent, left=-SX, top=top)
        else:
            place(agent, left=-SX, top=srv_cap.get_bottom()[1] - 0.35)   # landscape: under the server row
        mk, sv = marker(70), servers(70)

        self.P(FadeIn(hl), FadeIn(hpa), Create(track), FadeIn(ticks), FadeIn(ends), rt=0.8)
        self.P(FadeIn(mk), LaggedStart(*[GrowFromCenter(s) for s in sv], lag_ratio=0.04), FadeIn(srv_cap), rt=1.0)
        self.at(0.33)
        self.P(*([FadeOut(hpa)] if PORTRAIT else []), GrowFromCenter(agent[0]), FadeIn(agent[1]), rt=0.5)
        for i, t in enumerate((50, 80, 40, 60)):
            if i == 3:
                self.at(0.54)   # a steady state over 0.5, where GATE T samples (a mid-morph label is not type)
            self.P(Transform(mk, marker(t)), Transform(sv, servers(t)), rt=0.45)
            self.wait(0.3)
            self.el += 0.3
        self.at(0.6)
        # phase 2: the 35 numbers, as four rows of cells (bars = the example day's load at minute 235)
        t0 = 235 - X["lo"]
        series = [X["today"][t0 - 10:t0], X["yesterday"][t0:t0 + 10], X["last_week"][t0:t0 + 10]]
        vmax = max(max(s) for s in series)
        names = (("today, last 10 min", "yesterday, next 10", "last week, next 10", "servers, queue, time")
                 if PORTRAIT else ("today, last 10 minutes", "yesterday, next 10 minutes", "last week, next 10 minutes",
                                   "servers, queue, time of day"))
        colors = (SLATE, TEAL, GREY)
        title = place(T(f"It sees {O['size']} numbers" if PORTRAIT else f"Each minute it sees {O['size']} numbers",
                        size, weight="BOLD"), left=-SX, top=top)
        cw, ch, cg = (0.33, 0.34, 0.05) if PORTRAIT else (0.55, 0.72, 0.08)
        rows, bars = [], []
        y = title.get_bottom()[1] - (0.3 if PORTRAIT else 0.4)
        for i, (name, n) in enumerate(zip(names, O["groups"])):
            if i == 3:   # room under the history rows for the gold box and its note
                y -= 0.62 if PORTRAIT else 0.6
            cells = VGroup(*[Rectangle(width=cw, height=ch, stroke_color=SLATE, stroke_width=3, fill_opacity=0)
                             for _ in range(n)]).arrange(RIGHT, buff=cg)
            lab = T(name, 26 if PORTRAIT else 30)
            if PORTRAIT:
                place(lab, left=-SX, top=y)
                place(cells, left=-SX, top=lab.get_bottom()[1] - 0.05)
                y = cells.get_bottom()[1] - 0.16
            else:
                place(cells, left=-0.1, top=y)
                place(lab, left=-SX, y=cells.get_center()[1])
                y = cells.get_bottom()[1] - 0.36
            bs = VGroup()
            if i < 3:
                for c, v in zip(cells, series[i]):
                    h = max(0.9 * ch * v / vmax, 0.03)
                    bs.add(place(Rectangle(width=cw * 0.6, height=h, stroke_width=0, fill_color=colors[i], fill_opacity=1),
                                 x=c.get_center()[0], bottom=c.get_bottom()[1] + 0.04 * ch))
            rows.append(VGroup(lab, cells))
            bars.append(bs)
        past = SurroundingRectangle(VGroup(rows[1], rows[2]), buff=0.08, stroke_color=GOLD, stroke_width=7)
        note = place(T("the only past it sees" if PORTRAIT else "its only view of the past", size,
                       weight="NORMAL" if PORTRAIT else "BOLD"), left=-SX, top=past.get_bottom()[1] - 0.1)
        self.P(FadeOut(VGroup(hpa, agent, track, ticks, ends, mk, sv, srv_cap)), FadeIn(title), rt=0.5)
        for r, b in zip(rows, bars):
            anims = [FadeIn(r)] + ([LaggedStart(*[GrowFromEdge(x, DOWN) for x in b], lag_ratio=0.08)] if len(b) else [])
            self.P(*anims, rt=0.45)
        self.at(0.84)
        self.P(Create(past), FadeIn(note), rt=0.6)
        self.end()


# --------------------------------------------------------------------------------------------
# B03: one real Azure test day (evidence example): today and yesterday share a burst minute; then stress.py's
# three changes to yesterday (x0.2, x3, x0). The x3 line is clipped at the top of the chart and labelled.
# --------------------------------------------------------------------------------------------
class B03_History(Scene):
    BID, DEFAULT = "B03", 12.35

    def construct(self):
        self.begin()
        X = E["example"]
        lo, hi, burst = X["lo"], X["hi"], X["burst_minute"]
        xs = list(range(lo, hi + 1))
        hl = headline("One real day: the burst repeats", "One real day")
        size = 26 if PORTRAIT else 28
        sb = 0.1 if PORTRAIT else 0.16
        key = VGroup(swatch(SLATE, "today", "line", size, sb), swatch(TEAL, "yesterday", "line", size, sb)).arrange(
            RIGHT, buff=0.2 if PORTRAIT else 0.5)
        place(key, left=-SX, top=hl.get_bottom()[1] - 0.25)
        top = key.get_bottom()[1] - 0.75
        if PORTRAIT:
            box = Box(-SX + 0.82, top - 1.9, SX - 0.32, top, (lo, hi), (0, 26000))
            xt = [(m, str(m)) for m in (200, 260, 320)]
        else:
            box = Box(-SX + 1.05, -1.3, SX - 0.4, top, (lo, hi), (0, 26000))
            xt = [(m, str(m)) for m in range(200, 321, 20)]
        ax = axes(box, [(10000, "10k"), (20000, "20k")], xt, None, size=size)
        if PORTRAIT:
            ylab = place(T("requests a minute", size, SLATE), left=-SX, top=box.y0 - 0.55)
        else:
            ylab = VGroup(place(T("requests a minute", size, SLATE), left=-SX, bottom=box.y1 + 0.12),
                          place(T("x axis: minute of the day", size, SLATE), right=SX, y=key.get_center()[1]))
        today = box.line(xs, X["today"], SLATE, 5)
        yest = box.line(xs, X["yesterday"], TEAL, 5)
        bx = box.p(burst, 0)[0]
        same = DashedLine(box.p(burst, 0), box.p(burst, 26000), stroke_color=INK, stroke_width=3, dash_length=0.08)
        above = box.y1 + 0.12
        same_t = clamp(place(T("same minute", size, weight="BOLD"), left=bx + 0.15, bottom=above))
        b0, b1 = box.p(burst - 3, 15000), box.p(burst, 15000)
        boot = VGroup(Line(b0, b1, stroke_color=CRIMSON, stroke_width=6),
                      Line(b0 + DOWN * 0.1, b0 + UP * 0.1, stroke_color=CRIMSON, stroke_width=6),
                      Line(b1 + DOWN * 0.1, b1 + UP * 0.1, stroke_color=CRIMSON, stroke_width=6))
        boot_t = T("3 min to boot", size, CRIMSON, weight="BOLD")
        if PORTRAIT:   # above the chart, where "same minute" was
            clamp(place(boot_t, right=bx - 0.1, bottom=above))
        else:          # inside the chart, left of the bracket, between the 10k and 20k gridlines
            place(boot_t, right=b0[0] - 0.12, y=b0[1])
        cs = 26 if PORTRAIT else 30
        changes = [("holiday: × 0.2", 0.2), ("launch: × 3", 3.0), ("metrics outage: 0", 0.0)]
        chips = [chip(s, size=cs) for s, _ in changes]
        if PORTRAIT:   # one slot: each change replaces the last
            for c in chips:
                place(c, left=-SX, top=ylab.get_bottom()[1] - 0.18)
        else:
            row = VGroup(*chips).arrange(RIGHT, buff=0.3)
            place(row, left=-SX, top=box.y0 - 0.65)
        hpa = place(T("HPA reads no history" if PORTRAIT else "HPA reads no history: only the current load", cs, SLATE),
                    left=-SX, top=chips[-1].get_bottom()[1] - (0.14 if PORTRAIT else 0.2))
        peak = 3 * max(X["yesterday"])
        launch_t = clamp(place(T(f"× 3: {k_label(peak)}, off the chart" if not PORTRAIT else f"× 3: {k_label(peak)}",
                                 size, CRIMSON, weight="BOLD"), left=bx + 0.15, bottom=above))

        self.P(FadeIn(hl), FadeIn(key), FadeIn(ax), FadeIn(ylab), rt=0.6)
        self.P(Create(today), Create(yest), rt=1.4)
        self.at(0.2)
        self.P(Create(same), FadeIn(same_t), rt=0.6)
        self.at(0.42)
        self.P(FadeOut(same_t), Create(boot), FadeIn(boot_t), rt=0.6)
        self.at(0.62)
        lines = [box.line(xs, [v * f for v in X["yesterday"]], TEAL, 7 if f == 0 else 5) for _, f in changes]
        self.P(FadeOut(VGroup(same, boot, boot_t)), Transform(yest, lines[0]), FadeIn(chips[0]), rt=0.6)
        self.at(0.74)
        self.P(Transform(yest, lines[1]), *([FadeOut(chips[0])] if PORTRAIT else []), FadeIn(chips[1]), FadeIn(launch_t),
               rt=0.6)
        self.at(0.85)
        self.P(Transform(yest, lines[2]), *([FadeOut(chips[1])] if PORTRAIT else []), FadeIn(chips[2]), FadeOut(launch_t),
               rt=0.5)
        self.P(FadeIn(hpa), rt=0.4)
        self.end()


