# --------------------------------------------------------------------------------------------
# B05: training with misleading history (train.real_traffic, bad_days = 0.3): 10 example episodes from the
# real draw rule (evidence training.cards, seeded), then 40 example factors on a log number line (training.dots).
# --------------------------------------------------------------------------------------------
class B05_Randomize(Scene):
    BID, DEFAULT = "B05", 13.03

    def construct(self):
        self.begin()
        R = E["training"]
        hl = headline("Train on misleading history", "Train on", "misleading history")
        size = 26 if PORTRAIT else 32
        top = hl.get_bottom()[1] - 0.3
        X = "×"
        fmt = lambda c: f"{X} {c['factor']:.2f}" if c["factor"] else "= 0"
        cols, cw, chh, gx, gy = (5, 0.62, 0.5, 0.18, 0.14) if PORTRAIT else (5, 2.3, 1.1, 0.27, 0.22)
        cards = VGroup()
        for i, c in enumerate(R["cards"]):
            if PORTRAIT:   # numbered cards; the changes are listed under them
                txt = T(str(i + 1), size, INK if c else SLATE, weight="BOLD" if c else "NORMAL")
            elif c:
                txt = stack(c["day"], fmt(c), size=size, weight="BOLD", buff=0.02, aligned=ORIGIN)
            else:
                txt = T("normal", size, SLATE)
            box = RoundedRectangle(width=cw, height=chh, corner_radius=0.1, stroke_color=SLATE, stroke_width=3,
                                   fill_opacity=0)
            cards.add(VGroup(box, txt.move_to(box)))
        cards.arrange_in_grid(cols=cols, buff=(gx, gy))
        place(cards, left=-SX, top=top)
        flags = VGroup(*[SurroundingRectangle(cd[0], buff=0.04, stroke_color=GOLD, stroke_width=7, corner_radius=0.12)
                         for cd, c in zip(cards, R["cards"]) if c])
        normal_txt = VGroup(*[cd[1] for cd, c in zip(cards, R["cards"]) if not c])
        changed_txt = VGroup(*[cd[1] for cd, c in zip(cards, R["cards"]) if c])
        n_changed = sum(1 for c in R["cards"] if c)
        share = place(T(f"{n_changed} of {len(R['cards'])}: {R['share_pct']}%" if PORTRAIT else
                        f"{n_changed} of {len(R['cards'])} episodes: {R['share_pct']}%", size, weight="BOLD"),
                      left=-SX, top=cards.get_bottom()[1] - 0.2)
        if PORTRAIT:
            listing = stack(*[f"{i + 1}: {c['day']} {fmt(c)}" for i, c in enumerate(R["cards"]) if c], size=26,
                            weight="BOLD", buff=0.08)
            place(listing, left=-SX, top=share.get_bottom()[1] - 0.25)
            changed_txt = VGroup(changed_txt, listing)
        # phase 2: a number line with 40 example draws (zeros in a 3-wide stack at 0). Portrait: it replaces the
        # cards; landscape: it sits under them.
        fl = FactorLine(0.45 if PORTRAIT else -2.35, 26 if PORTRAIT else 30)
        sp, rad = (0.11, 0.05) if PORTRAIT else (0.15, 0.07)
        dots, seen, nz = VGroup(), {}, 0
        for f in R["dots"]:
            if f <= 0:
                x, n = fl.z + (nz % 3 - 1) * sp, nz // 3
                nz += 1
            else:
                b = round((fl.x(f) - fl.x0) / sp)
                n = seen.get(b, 0)
                seen[b] = n + 1
                x = fl.x0 + b * sp
            dots.add(Dot([x, fl.y + sp + n * sp, 0], radius=rad, color=TEAL))
        dlab = place(T("40 example factors", 26 if PORTRAIT else 30, SLATE), left=-SX,
                     bottom=max(d.get_top()[1] for d in dots) + 0.15)
        dr = (chip("domain", "randomization:", "randomize what can", "go wrong in training", size=26) if PORTRAIT else
              chip("domain randomization: randomize what can go wrong", "in training, so the policy does not depend on it",
                   size=32))
        place(dr, left=-SX, top=fl.ticks.get_bottom()[1] - 0.45 if PORTRAIT else 1.1)

        self.P(FadeIn(hl), rt=0.4)
        self.P(LaggedStart(*[FadeIn(cd[0]) for cd in cards], lag_ratio=0.08), FadeIn(normal_txt), rt=1.2)
        self.at(0.22)
        self.P(LaggedStart(*[GrowFromCenter(f) for f in flags], lag_ratio=0.2), FadeIn(changed_txt), FadeIn(share), rt=1.0)
        self.at(0.45)
        old = VGroup(cards, flags, share, changed_txt)
        self.P(*([FadeOut(old)] if PORTRAIT else []), Create(fl.axis), FadeIn(fl.ticks), FadeIn(dlab), rt=0.6)
        self.P(LaggedStart(*[FadeIn(d, shift=DOWN * 0.3) for d in dots], lag_ratio=0.05), rt=1.2)
        self.at(0.6)
        self.P(*([] if PORTRAIT else [FadeOut(old)]), GrowFromCenter(dr[0]), FadeIn(dr[1]), rt=0.6)
        self.end()


