# B06: the agent trained with misleading history on the same 360 cases, then normal history (60 runs each)
# (evidence stress.misleading and stress.normal: grid, better, worst, normal, normal_grid).
# --------------------------------------------------------------------------------------------
class B06_Result(Scene):
    BID, DEFAULT = "B06", 11.90

    def construct(self):
        self.begin()
        A, B = ST["normal"], ST["misleading"]
        hl = headline("Trained with misleading history", "Misleading history")
        size = 26 if PORTRAIT else 28
        sub = place(T("the same 360 cases" if PORTRAIT else "the same 360 cases, each vs HPA at the same cost",
                      26 if PORTRAIT else 30),
                    left=-SX, top=hl.get_bottom()[1] - 0.2)
        rtop = sub.get_bottom()[1] - (0.16 if PORTRAIT else 0.35)
        rows, fa, ca, cells_by = case_rows("normal", rtop)
        _, fb, cb, _ = case_rows("misleading", rtop)
        if PORTRAIT:
            t1 = place(T(f"better: {B['better']}, was {A['better']}", size, weight="BOLD"), left=-SX,
                       top=rows.get_bottom()[1] - 0.12)
            t2 = place(T(f"worst: +{B['worst_pct']}% late", size, weight="BOLD"), left=-SX, top=t1.get_bottom()[1] - 0.06)
        else:
            t1 = place(T(f"{B['better']} of 360 better ({B['pct']}%), was {A['better']}", 30, weight="BOLD"), left=-SX,
                       top=rows.get_bottom()[1] - 0.3)
            t2 = place(T(f"worst case: +{B['worst_pct']}% late, was +{A['worst_pct']}%", 30, weight="BOLD"), left=-SX,
                       top=t1.get_bottom()[1] - 0.14)
        wa, wb = worst_mark(cells_by, "normal"), worst_mark(cells_by, "misleading")
        # phase 2: normal history, 60 runs per agent
        nh = place(T("normal history" if PORTRAIT else "normal history: 60 runs each vs HPA, same cost",
                     26 if PORTRAIT else 30, weight="BOLD"), left=-SX, top=sub.get_top()[1])
        blocks, nfill = VGroup(), VGroup()
        y = nh.get_bottom()[1] - 0.4
        sq, gap = (0.105, 0.022) if PORTRAIT else (0.21, 0.045)
        names = (("normal training", "misleading training") if PORTRAIT else
                 ("trained on normal history", "trained with misleading history"))
        for agent, name in zip(("normal", "misleading"), names):
            bits = ST[agent]["normal_grid"]
            cells = VGroup(*[Square(sq, stroke_color=SLATE, stroke_width=2.5, fill_opacity=0) for _ in range(60)])
            cells.arrange_in_grid(rows=2, cols=30, buff=gap)
            lab = T(name, 26 if PORTRAIT else 30)
            cnt = T(f"{bits.count('1')} of 60 beat HPA", 26 if PORTRAIT else 30, weight="BOLD")
            place(lab, left=-SX, top=y)
            place(cells, left=-SX, top=lab.get_bottom()[1] - 0.12)
            place(cnt, left=-SX, top=cells.get_bottom()[1] - 0.12)
            y = cnt.get_bottom()[1] - (0.4 if PORTRAIT else 0.5)
            blocks.add(VGroup(lab, cells, cnt))
            nfill.add(VGroup(*[Square(sq, stroke_width=0, fill_color=TEAL, fill_opacity=1).move_to(c)
                               for c, b in zip(cells, bits) if b == "1"]))

        self.P(FadeIn(hl), FadeIn(sub), FadeIn(rows), FadeIn(fa), FadeIn(ca), FadeIn(wa), rt=0.5)
        self.at(0.06)
        self.P(LaggedStart(*[AnimationGroup(FadeOut(a), FadeIn(b)) for a, b in zip(fa, fb)], lag_ratio=0.12),
               *[Transform(a, b) for a, b in zip(ca, cb)], FadeIn(t1), rt=1.4)
        self.at(0.24)
        self.P(Transform(wa, wb), FadeIn(t2), rt=0.7)
        self.at(0.4)   # the switch ends before 0.5, where Gate V samples a steady state
        self.P(FadeOut(VGroup(sub, rows, fb, ca, wa, t1, t2)), FadeIn(nh), rt=0.5)
        self.P(FadeIn(blocks[0][0]), FadeIn(blocks[0][1]), rt=0.4)
        self.P(LaggedStart(*[GrowFromCenter(s) for s in nfill[0]], lag_ratio=0.01), FadeIn(blocks[0][2]), rt=0.8)
        self.at(0.72)
        self.P(FadeIn(blocks[1][0]), FadeIn(blocks[1][1]), rt=0.4)
        self.P(LaggedStart(*[GrowFromCenter(s) for s in nfill[1]], lag_ratio=0.01), FadeIn(blocks[1][2]), rt=0.8)
        self.end()


