# B07: limits. Test changes (stress.py: x0.2, x3, x0) inside the training range (real_traffic: x0.1 to x5, or 0);
# real irregular days come next; HPA is never fooled by history, the agent still sometimes is.
# --------------------------------------------------------------------------------------------
class B07_Limits(Scene):
    BID, DEFAULT = "B07", 15.83

    def construct(self):
        self.begin()
        B = ST["misleading"]
        hl = headline("Limits", "Limits")
        size = 26 if PORTRAIT else 30
        cap = (stack("same kinds of", "change as training", size=26, buff=0.05) if PORTRAIT else
               T("tests use the same kinds of change as training", 32))
        place(cap, left=-SX, top=hl.get_bottom()[1] - 0.25)
        fl = FactorLine(cap.get_bottom()[1] - (1.0 if PORTRAIT else 1.45), size)
        rng = RoundedRectangle(width=fl.x1 - fl.x0 + 0.3, height=0.3, corner_radius=0.08, stroke_color=TEAL,
                               stroke_width=5, fill_opacity=0).move_to([(fl.x0 + fl.x1) / 2, fl.y, 0])
        zbox = RoundedRectangle(width=0.36, height=0.3, corner_radius=0.08, stroke_color=TEAL, stroke_width=5,
                                fill_opacity=0).move_to([fl.z, fl.y, 0])
        tr_lab = place(T("training range" if PORTRAIT else "training: × 0.1 to × 5, or 0", size, TEAL,
                         weight="BOLD"), left=-SX, bottom=fl.y + (0.48 if PORTRAIT else 0.56))
        tests = VGroup()
        for f in (0.2, 3.0, 0.0):
            tri = Triangle(stroke_width=0, fill_color=CRIMSON, fill_opacity=1).scale(0.12 if PORTRAIT else 0.17).rotate(PI)
            tests.add(place(tri, x=fl.x(f), bottom=fl.y + 0.2))   # just above the training-range outline
        te_lab = place(T("tests: × 0.2, × 3, 0", size, CRIMSON, weight="BOLD"), left=-SX,
                       top=fl.ticks.get_bottom()[1] - 0.14)
        if PORTRAIT:   # no box (the padding would cross the safe edge): a slate rule above the lines
            lines = stack("next: real irregular", "days, like a recorded", "outage in public web", "server logs",
                          size=26, buff=0.04)
            place(lines, left=-SX, top=te_lab.get_bottom()[1] - 0.35)
            bar = Rectangle(width=lines.width, height=0.07, stroke_width=0, fill_color=SLATE, fill_opacity=1)
            place(bar, left=-SX, bottom=lines.get_top()[1] + 0.1)
            nxt = VGroup(bar, lines)
        else:
            nxt = chip("next: real irregular days, like a recorded", "outage in public web server logs", size=32)
            place(nxt, left=-SX, top=te_lab.get_bottom()[1] - 0.3)
        rows = VGroup(swatch(SLATE, "HPA: never fooled by history" if not PORTRAIT else "HPA: never fooled", "outline", size),
                      swatch(CRIMSON, f"agent: worst case still +{B['worst_pct']}% late" if not PORTRAIT
                             else f"agent: worst +{B['worst_pct']}%", "outline", size)
                      ).arrange(DOWN, buff=0.12, aligned_edge=LEFT)
        place(rows, left=-SX, top=nxt.get_bottom()[1] - (0.2 if PORTRAIT else 0.25))

        self.P(FadeIn(hl), FadeIn(cap), Create(fl.axis), FadeIn(fl.ticks), rt=0.7)
        self.P(GrowFromCenter(rng), GrowFromCenter(zbox), FadeIn(tr_lab), rt=0.6)
        self.P(LaggedStart(*[FadeIn(t, shift=DOWN * 0.4) for t in tests], lag_ratio=0.3), FadeIn(te_lab), rt=0.9)
        self.at(0.3)
        self.P(GrowFromCenter(nxt[0]), FadeIn(nxt[1]), rt=0.6)
        self.at(0.72)
        self.P(LaggedStart(*[FadeIn(r) for r in rows], lag_ratio=0.4), rt=0.8)
        self.end()


